exercises.starter_code:
.fiche { display: flex; flex-direction: row; }
.entete { display: block; }
.details { display: block; }
.actions { display: flex; flex-direction: row-reverse; }
#suite { order: -1; }

exercises.solution:
.fiche {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 16px;
}
.entete {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}
.details {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}
.actions {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}
#retour, #suite { order: 0; }
